import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestComOIndiceJunto(unittest.TestCase):
    def test_numerar_coloca_posicao_e_item(self):
        """numerar devolve uma frase para cada item com a posicao dele"""
        self.assertEqual(rodar()["numerar"](["ana", "bia"]), ["0-ana", "1-bia"])

    def test_numerar_com_uma_lista_vazia(self):
        """numerar com lista vazia devolve lista vazia"""
        self.assertEqual(rodar()["numerar"]([]), [])

    def test_numerar_com_um_item(self):
        """numerar com um item devolve a posicao zero"""
        self.assertEqual(rodar()["numerar"](["caio"]), ["0-caio"])

